// Type annotation breaks the self-referential inference cycle (TS7022) that
// supazod emits for recursive json columns.
export const jsonSchema: z.ZodType<unknown> = z.lazy(() =>
  z
    .union([
      z.string(),
      z.number(),
      z.boolean(),
      z.record(z.string(), z.union([jsonSchema, z.undefined()])),
      z.array(jsonSchema),
    ])
    .nullable(),
);

